import io
import pandas as pd
import numpy as np

def solve(data):
    return float(pd.DataFrame(data['employees'])[['Salary','Experience']].corr().loc['Salary','Experience'])

import io
import pandas as pd
import numpy as np

def solve(data):
    return pd.get_dummies(pd.DataFrame(data['employees']),columns=['City'],prefix='City',dtype=int).to_dict(orient='records')

import io
import pandas as pd
import numpy as np

def solve(data):
    return pd.concat([pd.read_csv(io.StringIO(part)) for part in data['csv_files']],ignore_index=True).to_dict(orient='records')
